    if ch == ".":   union all four
    if ch == "/":   union(top, left), union(bottom, right)
    if ch == "\\":  union(top, right), union(bottom, left)
    if i + 1 < n:   union(bottom of (i, j), top of (i + 1, j))
    if j + 1 < n:   union(right of (i, j), left of (i, j + 1))
regions = number of groups of the 4 * n * n triangles

