#include <iostream>
#include <vector>
#include <string>
using namespace std;

vector<int> parent, sizes;

int findRoot(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

bool unite(int a, int b) {
    a = findRoot(a);
    b = findRoot(b);
    if (a == b) return false;
    if (sizes[a] < sizes[b]) swap(a, b);
    parent[b] = a;
    sizes[a] += sizes[b];
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<string> board(n);
    for (int i = 0; i < n; i++) {
        cin >> board[i];
    }

    int cells = (int)n;
    int total = 4 * cells * cells;
    parent.resize(total);
    sizes.assign(total, 1);
    for (int v = 0; v < total; v++) parent[v] = v;
    int groups = total;
    auto join = [&](int a, int b) {
        if (unite(a, b)) groups--;
    };
    for (int i = 0; i < cells; i++) {
        for (int j = 0; j < cells; j++) {
            int base = 4 * (i * cells + j);
            char ch = board[i][j];
            if (ch == '.') {
                join(base, base + 1);
                join(base + 1, base + 2);
                join(base + 2, base + 3);
            } else if (ch == '/') {
                join(base, base + 3);
                join(base + 2, base + 1);
            } else {
                join(base, base + 1);
                join(base + 2, base + 3);
            }
            if (i + 1 < cells) join(base + 2, 4 * ((i + 1) * cells + j));
            if (j + 1 < cells) join(base + 1, 4 * (i * cells + j + 1) + 3);
        }
    }
    cout << groups << "\n";

    return 0;
}

