import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static int[] parent;
    static int[] sizes;

    static int findRoot(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    static boolean unite(int a, int b) {
        a = findRoot(a);
        b = findRoot(b);
        if (a == b) return false;
        if (sizes[a] < sizes[b]) {
            int t = a;
            a = b;
            b = t;
        }
        parent[b] = a;
        sizes[a] += sizes[b];
        return true;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        String[] board = new String[(int) n];
        for (int i = 0; i < board.length; i++) {
            board[i] = next();
        }

        int cells = (int) n;
        int total = 4 * cells * cells;
        parent = new int[total];
        sizes = new int[total];
        for (int v = 0; v < total; v++) {
            parent[v] = v;
            sizes[v] = 1;
        }
        int groups = total;
        for (int i = 0; i < cells; i++) {
            for (int j = 0; j < cells; j++) {
                int base = 4 * (i * cells + j);
                char ch = board[i].charAt(j);
                int[][] pairs;
                if (ch == '.') pairs = new int[][] {{base, base + 1}, {base + 1, base + 2}, {base + 2, base + 3}};
                else if (ch == '/') pairs = new int[][] {{base, base + 3}, {base + 2, base + 1}};
                else pairs = new int[][] {{base, base + 1}, {base + 2, base + 3}};
                for (int[] pair : pairs) {
                    if (unite(pair[0], pair[1])) groups--;
                }
                if (i + 1 < cells && unite(base + 2, 4 * ((i + 1) * cells + j))) groups--;
                if (j + 1 < cells && unite(base + 1, 4 * (i * cells + j + 1) + 3)) groups--;
            }
        }
        System.out.println(groups);
    }
}
